WITH RECURSIVE thread AS (SELECT *, 0 AS "depth" FROM "comments" WHERE ("id" = '00000000-0000-0000-0002-900000000001') UNION ALL (SELECT "c".*, "t"."depth" + 1 FROM "comments" AS "c" INNER JOIN "thread" AS "t" ON ("c"."parent_id" = "t"."id"))) SELECT "content", "created_at", "depth", "id", "parent_id", "post_id", "updated_at", "user_id" FROM "thread" ORDER BY "depth" ASC, "created_at" ASC, "id" ASC;
